static int32_t r2u2_gumbo_absoluteValue(int32_t value);

static bool r2u2_gumbo_isNonNegative(int32_t value) {
  return ((value) >= (0));
}

static int32_t r2u2_gumbo_absoluteValue(int32_t value) {
  return ((((value) < (0))) ? (-value) : (value));
}

